SELECT FROM product WHERE workspace_id = #{workspaceId}
AND ( LOWER(name) COLLATE utf8mb4_bin LIKE LOWER(#{query}) COLLATE utf8mb4_bin OR LOWER(sku) COLLATE utf8mb4_bin LIKE LOWER(#{query}) COLLATE utf8mb4_bin OR LOWER(description) COLLATE utf8mb4_bin LIKE LOWER(#{query}) COLLATE utf8mb4_bin )
ORDER BY name, id

SELECT  FROM product
WHERE workspace_id = #{workspaceId}
  AND sku IN
  #{sku}
ORDER BY id

WITH candidates (candidate_index, sku) AS ( SELECT 0, product.sku FROM product WHERE workspace_id = #{workspaceId} AND 1 = 0 UNION ALL VALUES
ROW(#{candidateIndex}, #{sku})
) SELECT candidates.candidate_index, COUNT(*) OVER (PARTITION BY candidates.sku) AS equivalent_count, DENSE_RANK() OVER (ORDER BY candidates.sku) AS collation_order, product.id AS product_id, product.name AS product_name FROM candidates LEFT JOIN product ON product.workspace_id = #{workspaceId} AND product.sku = candidates.sku ORDER BY candidates.candidate_index

SELECT  FROM product
WHERE workspace_id = #{workspaceId} AND id = #{id}
